)

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n int
	var m int64
	fmt.Fscan(reader, &n, &m)

	a := make([]int64, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(reader, &a[i])
	}

	// Split the array into two halves
	mid := n / 2
	left := a[:mid]
	right := a[mid:]

	// Generate all subset sums modulo m for the left half
	leftSums := generateSubsetSums(left, m)
	// Generate all subset sums modulo m for the right half
	rightSums := generateSubsetSums(right, m)

	// Sort the right sums
	sort.Slice(rightSums, func(i, j int) bool {
		return rightSums[i] < rightSums[j]
	})

	maxVal := int64(0)

	for _, ls := range leftSums {
		// We want to find the largest rs such that (ls + rs) % m is maximized
		// (ls + rs) % m = ls + rs if ls + rs < m
		// (ls + rs) % m = ls + rs - m if ls + rs >= m
		// We want to maximize (ls + rs) % m
		// Case 1: ls + rs < m => value = ls + rs, so we want the largest rs < m - ls
		// Case 2: ls + rs >= m => value = ls + rs - m, so we want the largest rs such that ls + rs < 2m, i.e., rs < 2m - ls
		// But since rs < m, the maximum value in case 2 is when rs is as large as possible, i.e., rs close to m-1
		// Actually, let's think differently.
		// For a given ls, we want to find rs in rightSums that maximizes (ls + rs) % m.
		// (ls + rs) % m is maximized when ls + rs is just below m (giving value close to m-1) or when ls + rs is just below 2m (but since rs < m, ls + rs < 2m always, and (ls+rs)%m = ls+rs-m when ls+rs >= m).
		// So the maximum possible value for a fixed ls is:
		// - If there exists rs such that ls + rs < m, then the best is the largest rs < m - ls, giving value ls + rs.
		// - If there exists rs such that ls + rs >= m, then the best is the largest rs (which is rightSums[len-1]), giving value ls + rs - m.
		// But actually, we can just binary search for the largest rs such that rs < m - ls (for case 1), and also consider the largest rs overall (for case 2, but case 2 value is ls + rs - m which is at most ls + (m-1) - m = ls - 1, which is less than m-1, while case 1 can give up to m-1).
		// Wait, let's reconsider. The maximum value of (ls + rs) % m is at most m-1.
		// To get close to m-1, we want ls + rs to be close to m (but less than m) or close to 2m (but that's not possible since rs < m and ls < m, so ls+rs < 2m, and if ls+rs >= m, then (ls+rs)%m = ls+rs-m which is at most (m-1 + m-1) - m = m-2).
		// So the best is to find rs such that ls + rs is just below m.
		// So we binary search for the largest rs < m - ls.

		target := m - ls
		// Find the largest element in rightSums that is < target
		// Use binary search
		idx := sort.Search(len(rightSums), func(i int) bool {
			return rightSums[i] >= target
		})
		// idx is the first index where rightSums[idx] >= target
		// So the largest element < target is at idx-1
		if idx > 0 {
			rs := rightSums[idx-1]
			val := (ls + rs) % m
			if val > maxVal {
				maxVal = val
			}
		}
		// Also check if there's an element >= target, the smallest such element
		// If idx < len(rightSums), then rightSums[idx] >= target
		// In that case, (ls + rightSums[idx]) % m = ls + rightSums[idx] - m
		if idx < len(rightSums) {
			rs := rightSums[idx]
			val := (ls + rs) % m
			if val > maxVal {
				maxVal = val
			}
		}
	}

	fmt.Fprintln(writer, maxVal)
}

func generateSubsetSums(arr []int64, m int64) []int64 {
	n := len(arr)
	size := 1 << n
	sums := make([]int64, size)
	sums[0] = 0
	for i := 1; i < size; i++ {
		// Find the least significant bit that is set
		lb := i & (-i)
		// Index of that bit
		bitIndex := 0
		tmp := lb
		for tmp > 1 {
			tmp >>= 1
			bitIndex++
		}
		prev := i - lb
		sums[i] = (sums[prev] + arr[bitIndex]) % m
	}
	return sums
}
