func generateSubsetSums(arr []int64) []int64 {
	n := len(arr)
	size := 1 << n
	sums := make([]int64, size)
	for i := 0; i < size; i++ {
		var sum int64 = 0
		for j := 0; j < n; j++ {
			if i&(1<<j) != 0 {
				sum += arr[j]
			}
		}
		sums[i] = sum
	}
	return sums
}
