func generateSubsetSums(arr []int, m int) []int {
	n := len(arr)
	sizes := 1 << n
	sums := make([]int, 0, sizes)
	for i := 0; i < sizes; i++ {
		sum := 0
		for j := 0; j < n; j++ {
			if i&(1<<j) != 0 {
				sum = (sum + arr[j]) % m
			}
		}
		sums = append(sums, sum)
	}
	return sums
}
