	fmt.Fprintln(writer, maxVal)
}

func generateSubsetSums(arr []int, m int) []int64 {
	n := len(arr)
	result := make([]int64, 0, 1<<n)
	for i := 0; i < (1 << n); i++ {
		sum := int64(0)
		for j := 0; j < n; j++ {
			if i&(1<<j) != 0 {
				sum += int64(arr[j])
			}
		}
		result = append(result, sum%int64(m))
	}
	return result
}
